            except (OverflowError, ValueError) as exc:
                raise non_finite() from exc
            terms.append(checked(term))
        try:
            total = math.fsum(terms)
        except (OverflowError, ValueError) as exc:
            raise non_finite() from exc
        return checked(-total)

