        c = 1.0
    else:
        try:
            c = mi / h_p
        except (OverflowError, ValueError) as exc:
            raise non_finite() from exc
        checked(c)

    try:
        d = beta_value * h + c
    except (OverflowError, ValueError) as exc:
        raise non_finite() from exc
    checked(d)
    if d == 0:
        v = 0.0
